from pathlib import Path
import sqlite3,json
w=Path(__file__).resolve().parent;c=sqlite3.connect('file:'+str(w/'input/index.sqlite3')+'?mode=ro',uri=True);c.row_factory=sqlite3.Row
sources={(r['path'],r['anchor']):dict(r) for r in c.execute('SELECT * FROM segments')};reports=json.loads((w/'input/report-ledger.json').read_text())
paths={'R':'response-playbook.docx.md','M':'maintenance-authorization.pdf.md','A':'containment-attestations.scan.pdf.md','T':'incident-timeline.md','N':'notification-register.md','G':'monitoring-coverage.md','F':'review-correspondence.md'}
def ev(m):
 p='input/sources/'+paths[m[0]];n=int(m[1:]);a=f'docx-p-{2*n+2:04d}' if m[0]=='R' else f'pdf-page-{n+1:04d}'+('-reviewed-0001' if m[0]=='A' else '') if m[0] in 'MA' else m
 d=sources[(p,a)];l=json.loads(d['locator']);return {'path':p,'anchor':a,'quote':d['quote'],'source_marker':m,'original_coordinate':{k:v for k,v in l.items() if k in ('original','original_sha256','page','member','xml_path','paragraph_index_in_story')}}
def pr(t,target,rel):return {'module':'Audit','theorem':'Audit.'+t,'target':target,'relation':rel}
f=[]
def add(i,q,markers,rules,reason,state,arg,formal,proofs,limits,reco,assumptions=None):
 k=f'C07-{i:02d}';f.append({'claim_id':k,'report_anchor':k,'report_quote':reports[k],'question':q,'evidence':[ev(m) for m in markers],'rules':rules,'assumptions':assumptions if assumptions is not None else ['Apply only the supplied synthetic playbook and its expressly authoritative event records for A/B/C during October 26-28, 2030. Exact minutes and numerical offsets are literal; no external timezone convention is assumed.','Material native-source text was inspected against original PDF pages or DOCX XML; independent datetime calculations are retained in arithmetic-check.md. This is source-to-model transcription, not live operational authentication.'],'reasoning':[str(j+1)+'. '+x for j,x in enumerate(reason)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':proofs,'limits':limits,'recommendation':reco})
add(1,'Was A qualifying detection exactly October 27 00:00 UTC, distinguishing accepted classification from the earlier raw warning?', ['R01','R02','T01'],['R01 defines qualifying detection as the coordinator-accepted classification. R02 converts UTC as local time minus the explicit numerical offset.'],['T01 separately records raw warning at 01:30 +02:00 and accepted P1 detection at 02:00 +02:00.','The accepted timestamp converts to 00:00 UTC on October 27. The raw warning converts to October 26 23:30 and cannot replace it.','The report exactly identifies the accepted-detection instant; the checked conversion supports it.'],'supported','sufficient','proved',[pr('claim01','Audit.aDetection = 0','supports')],['This establishes the supplied accepted event, not an independently measured earliest sensor anomaly.'],'Retain the detection timestamp and keep the raw warning in a separate field.')
add(2,'Is actual UTC elapsed time from A accepted local 02:00 +02:00 detection to local 03:20 +01:00 containment eighty minutes?', ['R02','T01','T02','F01'],['R02 requires one UTC timeline and each event\'s explicit offset; printed local labels with different offsets cannot be subtracted as one clock.'],['Detection converts to 00:00 UTC while containment converts to 02:20 UTC, using +02:00 and +01:00 respectively.','Elapsed time is 140 minutes, not the 80-minute difference of the local labels. F01 records that local-label calculation as struck out.','The exact 80-minute elapsed assertion is contradicted by the supplied timestamps and mandatory conversion rule.'],'refuted','invalid_inference','refuted',[pr('claim02','Audit.aElapsed = 140 ∧ Audit.aElapsed ≠ 80','refutes')],['This is raw elapsed time before permitted containment exclusions; active-response duration is a separate quantity.'],'Correct elapsed time to 140 minutes and show both explicit-offset conversions.')
add(3,'Did the actual delivered human acknowledgement of A satisfy the inclusive fifteen-minute P1 deadline after accepted detection?', ['R01','R02','R03','T01'],['R01 requires delivered human acknowledgement accepting responsibility; R03 allows 15 elapsed minutes for P1 without pauses or deferral.'],['T01 records accepted detection 00:00 UTC and a delivered human acknowledgement taking responsibility at 00:12 UTC.','Twelve elapsed minutes is within the inclusive fifteen-minute allowance.','The support is an actual delivered acknowledgement, not queueing or informal awareness.'],'supported','sufficient','proved',[pr('claim03','Audit.aAcknowledgement - Audit.aDetection = 12 ∧ Audit.aAcknowledgement ≤ Audit.aDetection + 15','supports')],['This says nothing by itself about containment or separate escalation duties.'],'Retain the timely acknowledgement finding separately from other duties.')
add(4,'After valid pause overlap and the applicable combined revision cap, was A active containment time eighty minutes?', ['R02','R04','R06','T01','T02','T03','F02'],['R04 deducts min(total approved overlapping pause duration, applicable combined cap). R06 assigns revision2 to accepted detection exactly at the boundary; its cap is45.'],['A actual UTC elapsed interval is 140 minutes. T03 establishes valid nonoverlapping pauses of30 and40 minutes entirely within that interval.','Their raw sum70 is capped at45 because accepted detection0 selects revision2. Active time is140-45=95.','Eighty would result from improperly deducting the old60-minute revision1 cap. The actual prescribed metric is95, refuting the report value.'],'refuted','invalid_inference','refuted',[pr('claim04','Audit.activeA = 95 ∧ Audit.activeA ≠ 80','refutes')],['Both pause approvals can be valid while their combined full duration remains nondeductible.'],'Replace eighty with ninety-five active-response minutes and identify the revision2 combined cap.')
add(5,'Did A meet its inclusive ninety-minute active-response containment SLA after the permissible capped deduction?', ['R03','R04','R06','T01','T02','T03','F02'],['R03 allows90 active minutes; R04/R06 require140 elapsed minus min(70,45), not uncapped or revision1 deductions.'],['Actual active time is95 minutes after both valid pauses and the combined45-minute cap.','Ninety-five exceeds the inclusive90-minute limit by5.','The reported SLA success is directly refuted by the correctly computed metric, regardless of A\'s timely acknowledgement.'],'refuted','invalid_inference','refuted',[pr('claim05','¬ (Audit.activeA ≤ 90) ∧ Audit.activeA - 90 = 5','refutes')],['This is a five-minute containment-SLA failure under the fictional playbook, not a verdict on every aspect of response quality.'],'Record a five-minute containment breach and retain separate outcomes for acknowledgement/escalation.')
add(6,'Does approval of both A pause intervals before their starts permit deduction of all seventy minutes despite the applicable combined cap?', ['R04','R06','T01','T02','T03','N03'],['Valid advance commander approval and eligible overlap are necessary but do not waive R04 combined cap; revision2 cap45 applies to the total, not each interval independently.'],['Approvals at00:25 and01:05 precede starts00:30 and01:10; documented external dependencies and interval endpoints satisfy approval/overlap requirements.','Durations30 and40 are disjoint and both within detection-to-containment, giving70 raw approved minutes.','R04 still limits combined exclusion to45. The report\'s approval-validity premise is true but its full-deduction conclusion is false; N03 calls the uncapped70 calculation provisional.'],'refuted','invalid_inference','refuted',[pr('claim06','Audit.pauseConditions = true ∧ Audit.rawPauseA = 70 ∧ Audit.excludedA = 45 ∧ Audit.excludedA < Audit.rawPauseA','refutes')],['No conclusion invalidates the pause approvals themselves or permits subtracting the cap from unrelated clocks.'],'Distinguish70 approved minutes from45 deductible minutes.')
add(7,'Does A P1 security classification allow MA-27 maintenance to defer its response-clock start from accepted detection00:00 to03:00 UTC?', ['R03','R07','M01','M02','M05','T01'],['R07 gives P1 precedence over maintenance deferral. M01 covers named P2 indexing alarms only; M02 defers only a matching P2 acknowledgement clock.'],['A detection lies temporally within MA-27 [00:00,03:00), but T01 identifies a P1 security incident, not its named expected P2 indexing operation.','Thus both the priority and operational-scope requirements for deferral fail. Shared infrastructure alone is insufficient.','A acknowledgement and containment clocks retain actual detection00:00; only separately valid containment exclusions affect the latter metric. The asserted03:00 clock start is refuted.'],'refuted','invalid_inference','refuted',[pr('claim07','Audit.aEffectiveStart = 0 ∧ Audit.aEffectiveStart ≠ 180','refutes')],['This does not deny the maintenance work or its possible scoped P2 effects; it denies transferring that exception to A.'],'Use A accepted detection00:00 and preserve MA-27 scope restrictions.')
add(8,'Did B delivered acknowledgement03:45 satisfy its inclusive30-minute allowance after the authorized MB-27 deferral?', ['R01','R03','R07','M02','M03','M04','T04','F03'],['M02 defers the clock for a matching P2 detection inside the half-open authorized window to that window\'s end; allowance30 then runs inclusively.'],['T04/M03 identify B as P2 operationM-B, with actual accepted detection03:10 inside MB-27 [02:50,03:20).','Effective acknowledgement start is03:20, while actual detection remains03:10. The delivered responsibility-taking acknowledgement is03:45.','The effective interval is25 minutes, within30; operator earlier contact is not substituted for the actual acknowledgement.'],'supported','sufficient','proved',[pr('claim08','(170 : Int) ≤ Audit.bDetection ∧ Audit.bDetection < 200 ∧ Audit.bEffectiveStart = 200 ∧ Audit.bAcknowledgement - Audit.bEffectiveStart = 25 ∧ Audit.bAcknowledgement ≤ Audit.bEffectiveStart + 30','supports')],['The exception changes one acknowledgement metric, not B existence/detection or any P1 duty.'],'Retain the result with actual detection03:10, effective start03:20 and deadline03:50 stated separately.')
add(9,'Does the true35-minute raw B detection-to-acknowledgement interval establish a30-minute allowance violation when MB-27 deferral applies?', ['R03','M02','M03','M04','T04','F03'],['The applicable P2 allowance runs from the authorized effective start, not necessarily actual detection.'],['Raw03:10-to03:45 elapsed time is35 minutes; that numerical premise is true.','The matching P2 maintenance rule shifts effective start to03:20, yielding25 minutes and a03:50 deadline.','Actual03:45 acknowledgement is timely, so the claimed violation is refuted because it applies the wrong clock.'],'refuted','invalid_inference','refuted',[pr('claim09','Audit.bAcknowledgement - Audit.bDetection = 35 ∧ Audit.bAcknowledgement ≤ Audit.bEffectiveStart + 30','refutes')],['A raw interval exceeding30 is not automatically late in this explicitly scoped exception; no general maintenance exemption follows.'],'Replace violation with timely acknowledgement under the authorized25-minute effective interval.')
add(10,'Did queueing A technical-lead notice at00:08 satisfy the delivered-notification duty by00:10?', ['R05','N01','N04','N03'],['R05 counts confirmed delivery to the required role; queue submission is a different event. N01 covers all such deliveries and explicitly excludes any earlier one.'],['N01 records queue00:08 but actual technical-lead delivery00:11 with a receipt token.','The required deadline is accepted detection00:00 plus10 minutes, inclusive. Actual first delivery is one minute late.','Queue success or its green console display cannot substitute for delivery, so the report\'s timely conclusion is refuted while its queue timestamp remains true.'],'refuted','invalid_inference','refuted',[pr('claim10','Audit.technical.queued ≤ Audit.aDetection + 10 ∧ ¬ (Audit.technical.delivered ≤ Audit.aDetection + 10) ∧ Audit.technical.delivered = 11','refutes')],['The bounded no-earlier-delivery statement concerns this role/incident and covered interval, not all informal awareness.'],'Record technical-lead delivery one minute late and label queue and delivery fields separately.')
add(11,'Can containment-pause deductions make A commander notification at00:22 timely against the20-minute escalation deadline?', ['R04','R05','N02','N03','N04','T03'],['R05 escalation clocks use ordinary elapsed UTC time without containment-pause exclusions. R04 pauses affect containment only.'],['N02 records first commander delivery00:22 and explicitly excludes earlier delivery; the inclusive deadline is00:20.','No containment pause deduction applies to this clock. In any case the first approved pause begins00:30, after this delivery.','The notification is two minutes late. Later commander approvals do not retroactively alter its delivery, and the report\'s subtraction rule is inapplicable.'],'refuted','invalid_inference','refuted',[pr('claim11','Audit.commander.delivered = 22 ∧ ¬ (Audit.commander.delivered ≤ Audit.aDetection + 20)','refutes')],['This does not invalidate the commander\'s separate later pause approvals or determine other recipients\' timeliness.'],'Record the two-minute commander escalation delay without containment exclusions.')
add(12,'Did the sixty-minute uncontained trigger actually occur for A, and was executive notification delivered within the following inclusive15 minutes?', ['R05','T01','T02','N02','N04','F04'],['R05 triggers executive duty only if still uncontained60 elapsed minutes after detection, then requires delivery within15 minutes. No pause deductions apply.'],['T02 positively and authoritatively records A continuously uncontained until02:20, so it was uncontained at01:00; this is not an inference from missing telemetry.','The executive trigger is01:00 and deadline01:15. N02 gives actual executive-role delivery01:12.','Twelve minutes after a real trigger is timely. This separate success neither erases nor inherits earlier technical/commander lateness.'],'supported','sufficient','proved',[pr('claim12','Audit.aUncontainedAt (Audit.aDetection + 60) = true ∧ Audit.executiveDelivery - (Audit.aDetection + 60) = 12 ∧ Audit.executiveDelivery ≤ Audit.aDetection + 75','supports')],['This proves the particular triggered duty and delivery comparison, not blanket compliance of all escalations.'],'Retain as a separate timely executive stage with the positive uncontained-state evidence.')
add(13,'Does A raw warning before midnight select revision1 despite coordinator-accepted qualifying detection exactly at the revision2 boundary?', ['R01','R06','T01'],['R01 distinguishes raw signal from accepted detection; R06 explicitly rejects grandfathering from an earlier raw warning and includes the boundary in revision2.'],['The raw warning converts to October26 23:30, before transition, but remains untriaged.','The accepted qualifying detection is October27 00:00 and is unchanged.','Revision2 governs A. The report substitutes the wrong event for version selection and is refuted, despite correctly noting the earlier warning.'],'refuted','invalid_inference','refuted',[pr('claim13','Audit.aRaw = -30 ∧ Audit.aDetection = 0 ∧ Audit.revision Audit.aDetection = 2 ∧ Audit.revision Audit.aDetection ≠ 1','refutes')],['The revision change affects the pause cap only; acknowledgement, maintenance and escalation rules here apply to both versions.'],'Use revision2 for A and preserve separate warning/detection fields.')
add(14,'Does C accepted detection before the boundary retain revision1 despite later response activity on October27?', ['R02','R06','T05','A04'],['R06 retains the revision selected by qualifying detection throughout response; later activity does not reselect it.'],['T05 accepted detection01:50 +02:00 converts to October26 23:50 UTC, ten minutes before boundary.','R06 therefore retains revision1 for C even after midnight activities. A04 confirms neither signatory disputes that accepted detection.','Unresolved C containment time does not undermine this independent, authoritative detection/version result.'],'supported','sufficient','proved',[pr('claim14','Audit.cDetection = -10 ∧ Audit.revision Audit.cDetection = 1','supports')],['No C containment time, containment-SLA compliance or actual isolation event is thereby established.'],'Retain revision1 and keep the containment dispute separate.')
add(15,'What supports and denies complete C isolation exactly October27 05:00 UTC, given authentic but unreconciled attestations and no authoritative C containment record?', ['R01','R08','T05','A01','A02','A03','A04'],['Signed testimony is not an infallible world fact. No source priority, later-signature override, role-based infallibility or authoritative resolution is supplied.'],['A01 visually verified text has Elise Stone affirm full isolation at exactly05:00 with no path live afterward.','A02 visually verified text has Pavel Hart explicitly deny full isolation at05:00 and assert a C path remained live until05:20. The same incident, UTC instant and complete-isolation proposition are at issue.','A03 stipulates authentic signatures but no retraction, adjudication or priority rule. T05 deliberately provides no authoritative containment timestamp; A04 merely acknowledges receipt of statements.','The evidence state is both supporting and denying testimony. The auxiliary theorem records attributions without proving contradictory world facts or selecting a historical isolation time.'],'both','disputed','auxiliary',[pr('claim15Conflict','Audit.eliseAffirmsIsolation0500 = true ∧ Audit.pavelDeniesIsolation0500 = true','auxiliary')],['Visual correction of OCR resolves the transcribed05:00/05:30 characters, not the witness dispute. Authenticity is stipulated within the dossier, not independently cryptographically tested by this audit.'],'Display both attributed accounts and seek an authoritative trace or adopted resolution; do not settle the event by signing order.',['Original scan pages were actually viewed and controlled reviewed-0001 transcriptions preserve source hashes and original OCR.','Authenticity establishes attribution only; T05 authoritative detection must not be mistaken for authoritative containment.'])
add(16,'Does the supplied evidence rule out all A exfiltration during the missing01:10-01:40 UTC monitoring period?', ['R08','G01','G02','G03','G04','T02'],['Missing samples cannot establish event absence; even retained no-listed-alarm observations are not complete detection of every possible exfiltration under G02.'],['G01 certifies collection outside the gap and explicitly supplies no samples within [01:10,01:40).','G02 limits sensor signatures/thresholds; G04 supplies no redundant complete capture. Thus there is neither complete negative evidence for the gap nor a rule connecting alarm silence to no exfiltration.','T02 uncontained state is independently established but does not prove either event polarity. The storage ticket describes collector capacity, not attacker behavior.','Compatible hypothetical histories share missing gap samples and no listed retained alarms while differing on exfiltration. The negative report claim is insufficiently supported, not refuted by invented positive evidence.'],'undetermined','insufficient_support','auxiliary',[pr('gapAlternatives','Audit.possibleNoExfiltration.gapSamplesAvailable = false ∧ Audit.possibleExfiltration.gapSamplesAvailable = false ∧ Audit.possibleNoExfiltration.retainedListedAlarms = false ∧ Audit.possibleExfiltration.retainedListedAlarms = false ∧ Audit.possibleNoExfiltration.exfiltrationDuringGap = false ∧ Audit.possibleExfiltration.exfiltrationDuringGap = true','auxiliary')],['The model demonstrates non-entailment only. Actual exfiltration remains unknown, including from ordinary absence of alarms in functioning but incomplete sensors.'],'Report the monitoring support gap and obtain a properly scoped capture or other event-complete evidence before asserting no exfiltration.',['No missing sample is assigned a fabricated value; hypothetical event alternatives preserve all supplied observation limitations.'])
add(17,'Does absence of collector records establish positive exfiltration during A01:10-01:40 gap?', ['R08','G01','G02','G03','G04'],['Unavailable observation is not positive event evidence; G03 expressly attributes storage outage without identifying malicious action or successful protected-data transfer.'],['The collector lacks samples because its storage service was unavailable; the support ticket gives configured capacity as the observation-system cause.','No supplied source connects that outage to an attacker or an exfiltration event. The absent separate capture is also unknown, not an incriminating result.','A no-exfiltration history is compatible with the same gap, as is an exfiltration history. The auxiliary witness therefore blocks the claimed causal/evidential inference while leaving actual occurrence undetermined.'],'undetermined','insufficient_support','auxiliary',[pr('gapAlternatives','Audit.possibleNoExfiltration.gapSamplesAvailable = false ∧ Audit.possibleExfiltration.gapSamplesAvailable = false ∧ Audit.possibleNoExfiltration.retainedListedAlarms = false ∧ Audit.possibleExfiltration.retainedListedAlarms = false ∧ Audit.possibleNoExfiltration.exfiltrationDuringGap = false ∧ Audit.possibleExfiltration.exfiltrationDuringGap = true','auxiliary')],['This does not prove that exfiltration did not occur. It identifies the missing positive event premise rather than substituting a favorable invented history.'],'Remove the positive event conclusion unless separate transfer evidence is obtained; retain the collection failure as its own documented finding.',['The hypothetical alternatives are explanatory countermodels, not claims about unseen capture contents or actual attacker behavior.'])
add(18,'Do the playbook or supplied opinions define criteria sufficient to judge the overall response professionally managed and reassuring?', ['R08','F05'],['R08 provides no operational standard for professional management or emotional reassurance. Objective timing metrics do not define every broader evaluative adjective.'],['F05 supplies a manager opinion using the report adjectives and another employee opinion about avoidable delays, but neither an agreed rubric or outcome weighting.','The documented mixed timeliness record, C testimony conflict and A monitoring gap address distinct objective/evidential questions rather than a complete management-quality criterion.','Both qualitative components remain nonformal under this mandate. No formal proof of either favorable evaluation or its negation is justified.'],'not_applicable','nonformal','not_attempted',[],['This is undefined evaluation, not a finding that the response was unprofessional or unreassuring. Attributed opinions can be preserved as opinions.'],'Attribute the manager\'s wording or supply an agreed rubric and argument before assessing the qualitative conclusion.',['No external incident-response standard or unstated utility/comfort metric is imported.'])
import re
def readable(s):
 return re.sub(r'(?<=[a-z])(?=[0-9])', ' ', s).replace('A01:10', "A's 01:10")
for item in f:
 for field in ('question', 'recommendation'):
  item[field]=readable(item[field])
 for field in ('rules','assumptions','reasoning','limits'):
  item[field]=[readable(x) for x in item[field]]
(w/'findings.json').write_text(json.dumps(f,indent=2,ensure_ascii=False)+'\n');print('Wrote',len(f),'findings')
